insert into public.tests (id,title,class_level,subject,chapter,duration_minutes,total_marks,questions,attempt_limit,is_published) values ('test-c9-renaissance-60','{"en":"Class 9th Weekly Online Test - History (Chapters 1–3)","hi":"कक्षा 9 साप्ताहिक ऑनलाइन टेस्ट - इतिहास (अध्याय 1–3)"}'::jsonb,'9','History','अध्याय 1: सामाजिक एवं सांस्कृतिक पुनर्जागरण · अध्याय 2: राष्ट्रीय चेतना के तत्व · अध्याय 3: उदारवादी एवं राष्ट्रवादी (1857–1919)',60,60,'[{"id":"c9-q1","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Swami Dayanand Saraswati","Raja Ram Mohan Roy","Swami Vivekananda","Jyotirao Phule"],"hi":["स्वामी दयानंद सरस्वती","राजा राममोहन राय","स्वामी विवेकानंद","ज्योतिबा फुले"]},"question":{"en":"Who founded the Brahmo Samaj?","hi":"ब्रह्म समाज की स्थापना किसने की थी?"}},{"id":"c9-q2","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["1818 AD","1828 AD","1857 AD","1875 AD"],"hi":["1818 ई.","1828 ई.","1857 ई.","1875 ई."]},"question":{"en":"When was Brahmo Samaj founded by Raja Ram Mohan Roy?","hi":"राजा राममोहन राय ने ब्रह्म समाज की स्थापना कब की थी?"}},{"id":"c9-q3","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Raja Ram Mohan Roy","Bal Gangadhar Tilak","Lala Lajpat Rai","Gopal Krishna Gokhale"],"hi":["राजा राममोहन राय","बाल गंगाधर तिलक","लाला लाजपत राय","गोपाल कृष्ण गोखले"]},"question":{"en":"Who played a key role against the practice of Sati?","hi":"सती प्रथा के विरोध में प्रमुख भूमिका किसने निभाई?"}},{"id":"c9-q4","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Swami Vivekananda","Swami Dayanand Saraswati","Raja Ram Mohan Roy","Jyotirao Phule"],"hi":["स्वामी विवेकानंद","स्वामी दयानंद सरस्वती","राजा राममोहन राय","ज्योतिबा फुले"]},"question":{"en":"Who founded the Arya Samaj?","hi":"आर्य समाज की स्थापना किसने की थी?"}},{"id":"c9-q5","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["1828 AD","1856 AD","1875 AD","1897 AD"],"hi":["1828 ई.","1856 ई.","1875 ई.","1897 ई."]},"question":{"en":"In which year was Arya Samaj founded?","hi":"आर्य समाज की स्थापना किस वर्ष हुई थी?"}},{"id":"c9-q6","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["1840 AD","1867 AD","1875 AD","1893 AD"],"hi":["1840 ई.","1867 ई.","1875 ई.","1893 ई."]},"question":{"en":"In which year was Prarthana Samaj founded?","hi":"प्रार्थना समाज की स्थापना किस वर्ष हुई थी?"}},{"id":"c9-q7","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Dr. Atmaram Pandurang","Mahatma Gandhi","Subhash Chandra Bose","Bhagat Singh"],"hi":["आत्माराम पांडुरंग","महात्मा गांधी","सुभाष चंद्र बोस","भगत सिंह"]},"question":{"en":"Who was the key social reformer associated with the founding of Prarthana Samaj?","hi":"प्रार्थना समाज की स्थापना से संबंधित प्रमुख समाज सुधारक कौन थे?"}},{"id":"c9-q8","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Ramakrishna Paramahamsa","Swami Vivekananda","Swami Dayanand Saraswati","Keshab Chandra Sen"],"hi":["रामकृष्ण परमहंस","स्वामी विवेकानंद","स्वामी दयानंद सरस्वती","केशवचंद्र सेन"]},"question":{"en":"Who founded the Ramakrishna Mission?","hi":"रामकृष्ण मिशन की स्थापना किसने की थी?"}},{"id":"c9-q9","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["1875 AD","1880 AD","1897 AD","1905 AD"],"hi":["1875 ई.","1880 ई.","1897 ई.","1905 ई."]},"question":{"en":"When was Ramakrishna Mission founded?","hi":"रामकृष्ण मिशन की स्थापना कब हुई थी?"}},{"id":"c9-q10","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Only political independence","Spiritual upliftment and service to humanity","Promoting foreign trade","Expansion of British rule"],"hi":["केवल राजनीतिक स्वतंत्रता","आध्यात्मिक उत्थान एवं मानव सेवा","विदेशी व्यापार बढ़ाना","अंग्रेजी शासन का विस्तार"]},"question":{"en":"What was the primary objective of Ramakrishna Mission?","hi":"रामकृष्ण मिशन का मुख्य उद्देश्य क्या था?"}},{"id":"c9-q11","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["1885 AD","1893 AD","1897 AD","1905 AD"],"hi":["1885 ई.","1893 ई.","1897 ई.","1905 ई."]},"question":{"en":"In which year did Swami Vivekananda participate in the World Parliament of Religions in Chicago?","hi":"स्वामी विवेकानंद ने शिकागो विश्व धर्म सम्मेलन में किस वर्ष भाग लिया?"}},{"id":"c9-q12","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Do or Die","Back to the Vedas","Jai Jawan Jai Kisan","Chalo Delhi"],"hi":["करो या मरो","वेदों की ओर लौटो","जय जवान जय किसान","दिल्ली चलो"]},"question":{"en":"Which was the principal slogan of Arya Samaj?","hi":"आर्य समाज का प्रमुख नारा कौन-सा था?"}},{"id":"c9-q13","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Ishwar Chandra Vidyasagar","Bal Gangadhar Tilak","Lala Lajpat Rai","Bipin Chandra Pal"],"hi":["ईश्वरचंद्र विद्यासागर","बाल गंगाधर तिलक","लाला लाजपत राय","बिपिन चंद्र पाल"]},"question":{"en":"Who played a foremost role in advocating for widow remarriage?","hi":"विधवा पुनर्विवाह के समर्थन में प्रमुख भूमिका किसने निभाई?"}},{"id":"c9-q14","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Jyotirao Phule","Lord Curzon","Lord Dalhousie","Lord Ripon"],"hi":["ज्योतिबा फुले","लॉर्ड कर्जन","लॉर्ड डलहौजी","लॉर्ड रिपन"]},"question":{"en":"Who among the following was a prominent social reformer fighting against caste discrimination?","hi":"जातिगत भेदभाव के विरोध से संबंधित प्रमुख समाज सुधारक कौन थे?"}},{"id":"c9-q15","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Mahatma Gandhi","Jyotirao Phule","Swami Vivekananda","Raja Ram Mohan Roy"],"hi":["महात्मा गांधी","ज्योतिबा फुले","स्वामी विवेकानंद","राजा राममोहन राय"]},"question":{"en":"Who founded the Satyashodhak Samaj?","hi":"सत्यशोधक समाज की स्थापना किसने की थी?"}},{"id":"c9-q16","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Social inequality and caste discrimination","Modern education","Women education","Industrial development"],"hi":["सामाजिक असमानता एवं जातिगत भेदभाव","आधुनिक शिक्षा","महिला शिक्षा","औद्योगिक विकास"]},"question":{"en":"Against what did Dr. B.R. Ambedkar primarily wage his struggle?","hi":"डॉ. भीमराव अंबेडकर ने किसके विरुद्ध संघर्ष किया?"}},{"id":"c9-q17","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Promoting social evils","Undertaking social and religious reforms","Opposing modern education","Increasing caste divisions"],"hi":["सामाजिक कुरीतियों को बढ़ावा देना","सामाजिक एवं धार्मिक सुधार करना","शिक्षा का विरोध करना","जातिगत भेदभाव बढ़ाना"]},"question":{"en":"What was the main goal of the Indian Renaissance?","hi":"भारतीय पुनर्जागरण का प्रमुख उद्देश्य क्या था?"}},{"id":"c9-q18","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Social reform movements","Imperialist expansion","Military organization","Foreign commerce"],"hi":["सामाजिक सुधार आंदोलन","साम्राज्यवादी विस्तार","सैन्य संगठन","विदेशी व्यापार"]},"question":{"en":"The promotion of women''s education is directly related to which movement?","hi":"महिला शिक्षा के प्रसार का संबंध किससे है?"}},{"id":"c9-q19","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Female education","Sati practice","Modern scientific education","Social equality"],"hi":["महिला शिक्षा","सती प्रथा","आधुनिक शिक्षा","सामाजिक समानता"]},"question":{"en":"Which practice was strongly opposed by Indian social reform movements?","hi":"भारतीय समाज सुधार आंदोलनों ने किस प्रथा का विरोध किया?"}},{"id":"c9-q20","chapter":"अध्याय 1: भारत का सामाजिक एवं सांस्कृतिक पुनर्जागरण","options":{"en":["Growth in social and political awareness","Demise of education","Support for caste evils","Resistance to reforms"],"hi":["सामाजिक जागरूकता में वृद्धि","शिक्षा का अंत","जातिगत भेदभाव का समर्थन","सामाजिक सुधारों का विरोध"]},"question":{"en":"What was the primary outcome of the socio-cultural renaissance?","hi":"सामाजिक एवं सांस्कृतिक पुनर्जागरण का प्रमुख परिणाम क्या था?"}},{"id":"c9-q21","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","options":{"en":["Socio-religious reform movements","Only overseas trade","Only military operations","Only natural calamities"],"hi":["सामाजिक एवं धार्मिक सुधार आंदोलन","केवल विदेशी व्यापार","केवल सैन्य गतिविधियाँ","केवल प्राकृतिक आपदाएँ"]},"question":{"en":"What contributed significantly to the growth of national consciousness in India?","hi":"भारत में राष्ट्रीय चेतना के विकास में किसका योगदान था?"}},{"id":"c9-q22","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","options":{"en":["Brahmo Samaj","Arya Samaj","Prarthana Samaj","Satyashodhak Samaj"],"hi":["ब्रह्म समाज","आर्य समाज","प्रार्थना समाज","सत्यशोधक समाज"]},"question":{"en":"Which organization was founded by Swami Dayanand Saraswati?","hi":"स्वामी दयानंद सरस्वती ने किस संगठन की स्थापना की?"}},{"id":"c9-q23","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","options":{"en":["Humanitarian service and spiritual growth","Caste discrimination","Social disparity","Opposition to literacy"],"hi":["मानव सेवा एवं आध्यात्मिक विकास","जातिगत भेदभाव","सामाजिक असमानता","शिक्षा का विरोध"]},"question":{"en":"What did Swami Vivekananda especially emphasize?","hi":"स्वामी विवेकानंद ने किस बात पर विशेष बल दिया?"}},{"id":"c9-q24","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","options":{"en":["Spreading civic awareness among masses","Ending schooling","Resisting reforms","Strengthening colonial rule"],"hi":["जनता में जागरूकता फैलाना","शिक्षा समाप्त करना","सुधारों का विरोध","विदेशी शासन मजबूत करना"]},"question":{"en":"What role did newspapers play in cultivating Indian national consciousness?","hi":"भारतीय राष्ट्रीय चेतना के विकास में समाचार-पत्रों की क्या भूमिका थी?"}},{"id":"c9-q25","chapter":"अध्याय 2: राष्ट्रीय चेतना के तत्व","options":{"en":["Dadabhai Naoroji","Swami Vivekananda","Ramakrishna Paramahamsa","Raja Ram Mohan Roy"],"hi":["दादाभाई नौरोजी","स्