insert into public.tests (id,title,class_level,subject,chapter,duration_minutes,total_marks,questions,attempt_limit,is_published) values ('test-polity-constitution','{"en":"Indian Constitution & Polity: Fundamental Rights & Preamble Quiz","hi":"भारतीय संविधान एवं राजव्यवस्था: मौलिक अधिकार व प्रस्तावना क्विज"}'::jsonb,'9','Indian Constitution','Constitutional Design & Fundamental Rights',10,16,'[{"id":"cq1","chapter":"Preamble","options":{"en":["24th Amendment, 1971","42nd Amendment, 1976","44th Amendment, 1978","52nd Amendment, 1985"],"hi":["24वां संशोधन, 1971","42वां संशोधन, 1976","44वां संशोधन, 1978","52वां संशोधन, 1985"]},"question":{"en":"By which Constitutional Amendment were the words \"Socialist\", \"Secular\", and \"Integrity\" added to the Preamble of the Indian Constitution?","hi":"किस संविधान संशोधन द्वारा भारतीय संविधान की प्रस्तावना में \"समाजवादी\", \"धर्मनिरपेक्ष\" (पंथनिरपेक्ष) और \"अखंडता\" शब्द जोड़े गए थे?"}},{"id":"cq2","chapter":"Fundamental Rights","options":{"en":["Article 14 (Right to Equality)","Article 19 (Right to Freedom)","Article 21 (Right to Life and Personal Liberty)","Article 32 (Right to Constitutional Remedies)"],"hi":["अनुच्छेद 14 (समानता का अधिकार)","अनुच्छेद 19 (स्वतंत्रता का अधिकार)","अनुच्छेद 21 (प्राण एवं दैहिक स्वतंत्रता)","अनुच्छेद 32 (संवैधानिक उपचारों का अधिकार)"]},"question":{"en":"Which Article was described by Dr. B.R. Ambedkar as the \"Heart and Soul of the Constitution\"?","hi":"डॉ. बी.आर. आंबेडकर ने किस अनुच्छेद को \"संविधान का हृदय और आत्मा\" कहा था?"}},{"id":"cq3","chapter":"Constituent Assembly","options":{"en":["Dr. Rajendra Prasad","Dr. B.R. Ambedkar","Pandit Jawaharlal Nehru","Sardar Vallabhbhai Patel"],"hi":["डॉ. राजेंद्र प्रसाद","डॉ. बी.आर. आंबेडकर","पंडित जवाहरलाल नेहरू","सरदार वल्लभभाई पटेल"]},"question":{"en":"Who served as the Chairman of the Drafting Committee of the Constituent Assembly?","hi":"संविधान सभा की प्रारूप समिति (Drafting Committee) के अध्यक्ष कौन थे?"}},{"id":"cq4","chapter":"Fundamental Rights","options":{"en":["3 to 6 years","6 to 14 years","6 to 18 years","Up to 12 years"],"hi":["3 से 6 वर्ष","6 से 14 वर्ष","6 से 18 वर्ष","12 वर्ष तक"]},"question":{"en":"Under Article 21A, free and compulsory education is guaranteed as a Fundamental Right for children of which age group?","hi":"अनुच्छेद 21A के अंतर्गत किस आयु वर्ग के बच्चों के लिए निःशुल्क और अनिवार्य शिक्षा मौलिक अधिकार बनाई गई है?"}}]'::jsonb,1,true)
