insert into public.tests (id,title,class_level,subject,chapter,duration_minutes,total_marks,questions,attempt_limit,is_published) values ('test-c10-resources-10','{"en":"Class 10 Geography – Resources and Development","hi":"कक्षा 10 भूगोल – संसाधन एवं विकास"}'::jsonb,'10','Geography','Resources and Development',15,10,'[{"id":"c10-rd-q1","options":{"en":["Being available only in nature","Having only economic value","Being technologically accessible, economically feasible and culturally acceptable","Being manufactured only by humans"],"hi":["केवल प्राकृतिक रूप से उपलब्ध होना","केवल आर्थिक रूप से मूल्यवान होना","तकनीकी रूप से सुलभ, आर्थिक रूप से व्यवहार्य और सांस्कृतिक रूप से स्वीकार्य होना","केवल मानव द्वारा निर्मित होना"]},"question":{"en":"What conditions make an object or substance a resource?","hi":"किसी वस्तु को संसाधन बनने के लिए कौन-सी शर्तें आवश्यक हैं?"}},{"id":"c10-rd-q2","options":{"en":["Equal distribution of resources","Resource depletion and environmental problems","Automatic increase in natural resources","Complete elimination of pollution"],"hi":["संसाधनों का समान वितरण","संसाधनों का क्षय और पर्यावरणीय समस्याएँ","प्राकृतिक संसाधनों में स्वतः वृद्धि","प्रदूषण का पूर्ण अंत"]},"question":{"en":"What is a major consequence of indiscriminate use of resources?","hi":"संसाधनों के अंधाधुंध उपयोग का प्रमुख परिणाम क्या है?"}},{"id":"c10-rd-q3","options":{"en":["Meeting only the needs of the present generation","Using all resources to the maximum","Prioritising only industrial development","Meeting present needs without compromising future generations"],"hi":["केवल वर्तमान पीढ़ी की आवश्यकताओं को पूरा करना","सभी संसाधनों का अधिकतम उपयोग करना","केवल औद्योगिक विकास को प्राथमिकता देना","भविष्य की पीढ़ियों की आवश्यकताओं से समझौता किए बिना वर्तमान आवश्यकताओं को पूरा करना"]},"question":{"en":"What is the correct meaning of sustainable development?","hi":"सतत विकास का सही अर्थ क्या है?"}},{"id":"c10-rd-q4","options":{"en":["New Delhi","Rio de Janeiro","London","New York"],"hi":["नई दिल्ली","रियो डी जेनेरियो","लंदन","न्यूयॉर्क"]},"question":{"en":"Where was the Earth Summit held in 1992?","hi":"पृथ्वी सम्मेलन (Earth Summit), 1992 का आयोजन कहाँ हुआ था?"}},{"id":"c10-rd-q5","options":{"en":["Promoting sustainable development","Ending world trade","Promoting only urbanisation","Privatising natural resources"],"hi":["सतत विकास को बढ़ावा देना","विश्व व्यापार को समाप्त करना","केवल शहरीकरण को बढ़ावा देना","प्राकृतिक संसाधनों का निजीकरण करना"]},"question":{"en":"What is the main objective of Agenda 21?","hi":"एजेंडा 21 का मुख्य उद्देश्य क्या है?"}},{"id":"c10-rd-q6","options":{"en":["Utilisation, export and conservation","Production, distribution and consumption","Identification and inventory, planning structure and integration with development plans","Mining, industrialisation and trade"],"hi":["उपयोग, निर्यात और संरक्षण","उत्पादन, वितरण और उपभोग","संसाधनों की पहचान एवं सूचीकरण, नियोजन संरचना बनाना और विकास योजनाओं से मिलान","खनन, औद्योगीकरण और व्यापार"]},"question":{"en":"Which is the correct sequence of resource planning in India?","hi":"भारत में संसाधन नियोजन की प्रक्रिया का सही क्रम कौन-सा है?"}},{"id":"c10-rd-q7","options":{"en":["It has very low moisture-retention capacity","It has high moisture-retention capacity","It is found only in desert regions","It is found only in mountainous regions"],"hi":["इसमें नमी धारण करने की क्षमता बहुत कम होती है","इसमें नमी धारण करने की क्षमता अधिक होती है","यह केवल रेगिस्तानी क्षेत्रों में पाई जाती है","यह केवल पर्वतीय क्षेत्रों में पाई जाती है"]},"question":{"en":"What is a major characteristic of black soil?","hi":"काली मिट्टी की प्रमुख विशेषता क्या है?"}},{"id":"c10-rd-q8","options":{"en":["Northern plains and eastern coastal deltas","Only in the Thar Desert","Only in the Deccan Plateau","Only on the high Himalayan peaks"],"hi":["उत्तरी मैदानों और पूर्वी तटीय डेल्टाओं में","केवल थार मरुस्थल में","केवल दक्कन के पठार में","केवल हिमालय की ऊँची चोटियों पर"]},"question":{"en":"Where is alluvial soil mainly found in India?","hi":"भारत में जलोढ़ मिट्टी मुख्य रूप से कहाँ पाई जाती है?"}},{"id":"c10-rd-q9","options":{"en":["Excessive expansion of forests","Formation of glaciers","Waterlogging and soil salinity due to over-irrigation","Sea waves"],"hi":["वनों का अत्यधिक विस्तार","हिमनदों का निर्माण","अति-सिंचाई के कारण जलभराव और मिट्टी की लवणता","समुद्री लहरें"]},"question":{"en":"What is a major cause of land degradation in Punjab, Haryana and western Uttar Pradesh?","hi":"पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश में भूमि निम्नीकरण का एक प्रमुख कारण क्या है?"}},{"id":"c10-rd-q10","options":{"en":["Ploughing down the slope","Deforestation","Overgrazing","Contour ploughing"],"hi":["ढाल की दिशा में जुताई","वनों की कटाई","अत्यधिक चराई","समोच्च रेखाओं के समानांतर जुताई"]},"question":{"en":"Which method helps reduce soil erosion on sloping land?","hi":"ढाल वाली भूमि पर मृदा अपरदन कम करने के लिए कौन-सी विधि उपयोगी है?"}}]'::jsonb,1,true)
